const liquidacion = $input.item.json;

// Validar que total existe
if (!liquidacion.total || liquidacion.total === null) {
  return {
    error: true,
    mensaje: `❌ Error: Liquidación ${liquidacion.id_liquidacion} sin total calculado. Revisar en la BD.`
  };
}

const total = parseFloat(liquidacion.total);
const alquilerBase = parseFloat(liquidacion.alquiler ?? liquidacion.alquiler_actual);
const mora2porciento = parseFloat((total * 0.02).toFixed(2));
const mora4porciento = parseFloat((total * 0.04).toFixed(2));
const totalCon2 = parseFloat((total + mora2porciento).toFixed(2));
const totalCon4 = parseFloat((total + mora4porciento).toFixed(2));

// Mes en texto (sin desfasaje de huso horario UTC-3)
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const [anioStr, mesStr] = String(liquidacion.mes_año).slice(0, 10).split('-');
const mesTexto = `${meses[parseInt(mesStr, 10) - 1]} de ${anioStr}`;

// Nombres de inquilinos
const nombresInquilinos = liquidacion.nombres_inquilinos || liquidacion.nombre;

// Servicios reales
const servicios = [
  { nombre: 'Luz', valor: liquidacion.luz },
  { nombre: 'Gas', valor: liquidacion.gas },
  { nombre: 'Agua', valor: liquidacion.agua },
  { nombre: 'Municipal', valor: liquidacion.municipal },
  { nombre: 'Expensas', valor: liquidacion.expensas },
  { nombre: 'Seguro', valor: liquidacion.seguro }
].filter(s => s.valor !== null && s.valor !== undefined);

let serviciosTexto = '';
if (servicios.length > 0) {
  serviciosTexto = '\nServicios:\n' + servicios.map(s =>
    `  • ${s.nombre}: $${parseFloat(s.valor).toLocaleString('es-AR')}`
  ).join('\n');
}

// Conceptos reales (separando adicionales y descuentos)
const conceptos = liquidacion.conceptos || [];
const adicionales = conceptos.filter(c => c.tipo !== 'descuento');
const descuentos = conceptos.filter(c => c.tipo === 'descuento');

let conceptosTexto = '';
if (adicionales.length > 0) {
  conceptosTexto += '\nAdicionales:\n' + adicionales.map(c =>
    `  • ${c.descripcion}: $${parseFloat(c.monto).toLocaleString('es-AR')}`
  ).join('\n');
}
if (descuentos.length > 0) {
  conceptosTexto += '\nDescuentos:\n' + descuentos.map(c =>
    `  • ${c.descripcion}: -$${parseFloat(c.monto).toLocaleString('es-AR')}`
  ).join('\n');
}

const mensaje = `Hola ${nombresInquilinos}, te pasamos tu liquidación de ${mesTexto}.\n\n📋 *DESGLOSE:*\nAlquiler: $${alquilerBase.toLocaleString('es-AR')}\n${serviciosTexto}${conceptosTexto}\n\n*TOTAL BASE: $${total.toLocaleString('es-AR')}*\n\n⚠️ *REGLAS DE PAGO:*\n- Hasta el día 20: $${total.toLocaleString('es-AR')}\n- Del 21 al 30 (+2%): $${totalCon2.toLocaleString('es-AR')}\n- Después del 30 (+4%): $${totalCon4.toLocaleString('es-AR')}\n\nℹ️ _Este es un mensaje automático (no respondas a este número). Comunicate con Laura o Martín para cualquier duda._`;

return {
  mensaje: mensaje,
  id_liquidacion: liquidacion.id_liquidacion,
  celular: liquidacion.celular || '',
  total: total,
  nombres_inquilinos: nombresInquilinos
};
